import{a as e,i as t,r as n,t as r}from"./app-DbTmPHyY.js";var i=JSON.parse(`{"path":"/%E7%AC%AC10%E7%AB%A0%20%E9%A1%B9%E7%9B%AE%E8%BF%9B%E5%BA%A6%E7%AE%A1%E7%90%86/10.2%20%E5%85%B3%E9%94%AE%E8%B7%AF%E5%BE%84%E6%B3%95.html","title":"10.2 关键路径法","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"第10章 项目进度管理/10.2 关键路径法.md"}`),a={name:`10.2 关键路径法.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="_10-2-关键路径法" tabindex="-1"><a class="header-anchor" href="#_10-2-关键路径法"><span>10.2 关键路径法</span></a></h1><h2 id="定义" tabindex="-1"><a class="header-anchor" href="#定义"><span>定义</span></a></h2><p>关键路径法（Critical Path Method，CPM）是一种用于确定项目最短工期的方法，通过分析活动之间的依赖关系，找出最长的路径（关键路径）。</p><h2 id="关键概念" tabindex="-1"><a class="header-anchor" href="#关键概念"><span>关键概念</span></a></h2><h3 id="_1-关键路径" tabindex="-1"><a class="header-anchor" href="#_1-关键路径"><span>1. 关键路径</span></a></h3><ul><li><strong>定义</strong>：项目中最长的路径，决定项目的最短工期</li><li><strong>特点</strong>：总浮动时间为零</li><li><strong>重要性</strong>：关键路径上的活动延误将直接导致项目延误</li></ul><h3 id="_2-总浮动时间" tabindex="-1"><a class="header-anchor" href="#_2-总浮动时间"><span>2. 总浮动时间</span></a></h3><ul><li><strong>定义</strong>：在不影响项目总工期的前提下，活动可以延迟的时间</li><li><strong>计算公式</strong>：最迟完成时间 - 最早完成时间</li></ul><h3 id="_3-自由浮动时间" tabindex="-1"><a class="header-anchor" href="#_3-自由浮动时间"><span>3. 自由浮动时间</span></a></h3><ul><li><strong>定义</strong>：在不影响后续活动最早开始时间的前提下，活动可以延迟的时间</li><li><strong>计算公式</strong>：后续活动最早开始时间 - 当前活动最早完成时间</li></ul><h3 id="_4-最早开始时间-es" tabindex="-1"><a class="header-anchor" href="#_4-最早开始时间-es"><span>4. 最早开始时间（ES）</span></a></h3><ul><li><strong>定义</strong>：活动最早可以开始的时间</li><li><strong>计算方法</strong>：从项目开始正向计算</li></ul><h3 id="_5-最早完成时间-ef" tabindex="-1"><a class="header-anchor" href="#_5-最早完成时间-ef"><span>5. 最早完成时间（EF）</span></a></h3><ul><li><strong>定义</strong>：活动最早可以完成的时间</li><li><strong>计算公式</strong>：ES + 活动历时</li></ul><h3 id="_6-最迟开始时间-ls" tabindex="-1"><a class="header-anchor" href="#_6-最迟开始时间-ls"><span>6. 最迟开始时间（LS）</span></a></h3><ul><li><strong>定义</strong>：活动最迟必须开始的时间</li><li><strong>计算方法</strong>：从项目结束反向计算</li></ul><h3 id="_7-最迟完成时间-lf" tabindex="-1"><a class="header-anchor" href="#_7-最迟完成时间-lf"><span>7. 最迟完成时间（LF）</span></a></h3><ul><li><strong>定义</strong>：活动最迟必须完成的时间</li><li><strong>计算公式</strong>：LS + 活动历时</li></ul><h2 id="关键路径法的步骤" tabindex="-1"><a class="header-anchor" href="#关键路径法的步骤"><span>关键路径法的步骤</span></a></h2><h3 id="_1-绘制项目进度网络图" tabindex="-1"><a class="header-anchor" href="#_1-绘制项目进度网络图"><span>1. 绘制项目进度网络图</span></a></h3><ul><li>确定活动之间的依赖关系</li><li>用节点表示活动，用箭头表示依赖关系</li></ul><h3 id="_2-计算最早时间" tabindex="-1"><a class="header-anchor" href="#_2-计算最早时间"><span>2. 计算最早时间</span></a></h3><ul><li>从项目开始正向计算</li><li>计算每个活动的ES和EF</li></ul><h3 id="_3-计算最迟时间" tabindex="-1"><a class="header-anchor" href="#_3-计算最迟时间"><span>3. 计算最迟时间</span></a></h3><ul><li>从项目结束反向计算</li><li>计算每个活动的LS和LF</li></ul><h3 id="_4-确定关键路径" tabindex="-1"><a class="header-anchor" href="#_4-确定关键路径"><span>4. 确定关键路径</span></a></h3><ul><li>找出总浮动时间为零的活动</li><li>这些活动组成关键路径</li></ul><h3 id="_5-优化关键路径" tabindex="-1"><a class="header-anchor" href="#_5-优化关键路径"><span>5. 优化关键路径</span></a></h3><ul><li>识别关键路径上的活动</li><li>采取措施缩短关键路径工期</li></ul><h2 id="关键路径的特点" tabindex="-1"><a class="header-anchor" href="#关键路径的特点"><span>关键路径的特点</span></a></h2><h3 id="_1-最长路径" tabindex="-1"><a class="header-anchor" href="#_1-最长路径"><span>1. 最长路径</span></a></h3><ul><li>关键路径是项目中最长的路径</li><li>决定项目的最短工期</li></ul><h3 id="_2-零浮动时间" tabindex="-1"><a class="header-anchor" href="#_2-零浮动时间"><span>2. 零浮动时间</span></a></h3><ul><li>关键路径上的活动总浮动时间为零</li><li>任何延误都会影响项目工期</li></ul><h3 id="_3-动态变化" tabindex="-1"><a class="header-anchor" href="#_3-动态变化"><span>3. 动态变化</span></a></h3><ul><li>关键路径可能随项目进展而变化</li><li>需要定期重新计算</li></ul><h2 id="关键考点" tabindex="-1"><a class="header-anchor" href="#关键考点"><span>关键考点</span></a></h2><ol><li><strong>关键路径的定义和特点</strong></li><li><strong>总浮动时间和自由浮动时间的区别</strong></li><li><strong>关键路径法的步骤</strong></li></ol><h2 id="记忆口诀" tabindex="-1"><a class="header-anchor" href="#记忆口诀"><span>记忆口诀</span></a></h2><p>关键路径最长，浮动时间决定灵活性，正向计算最早，反向计算最迟</p><h2 id="典型例题" tabindex="-1"><a class="header-anchor" href="#典型例题"><span>典型例题</span></a></h2><p><strong>例题</strong>：关键路径上的活动有什么特点？ A. 总浮动时间为零 B. 自由浮动时间为零 C. 活动历时最短 D. 活动历时最长</p><p><strong>答案</strong>：A</p><p><strong>解析</strong>：关键路径上的活动总浮动时间为零，任何延误都会直接影响项目总工期。</p>`,44)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};